tape( 'the function preserves a generic base ndarray when the output data type is float32', function test( t ) {
	var dtypes;
	var types;
	var base;
	var args;
	var out;

	base = scalar2ndarray( {}, {
		'dtype': 'generic'
	});
	types = [ ENUMS.NDARRAY, ENUMS.NUMBER, ENUMS.NUMBER, ENUMS.BOOLEAN ];
	dtypes = [ 'generic', 'float64', 'float64', 'bool', 'float32' ];
	args = [ base, 0.0, 2.0, true ];

	out = normalizeArguments( args, types, dtypes, [ 2, 3 ], 'row-major' );

	t.strictEqual( getDType( out[ 0 ] ), 'generic', 'returns expected value' );
	t.deepEqual( out[ 0 ].shape, [ 2, 3 ], 'returns expected value' );

	t.end();
});
